import re

def parse(lines):
    conf, gram, term, nont, items, acts = [], [], [], [], [], []
    ci, gi, ti, ni, ii, ai = [], [], [], [], [], []
    skip = []
    sec = None
    lhs = None
    state = None
    cur = None
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        m = re.match(r'^State (\d+) conflicts?: (.*)$', l)
        if m:
            sr = re.search(r'(\d+) shift/reduce', m.group(2))
            rr = re.search(r'(\d+) reduce/reduce', m.group(2))
            conf.append({'state': m.group(1), 'shift/reduce': sr.group(1) if sr else '', 'reduce/reduce': rr.group(1) if rr else ''})
            ci.append(i)
            continue
        if l == 'Grammar':
            sec = 'g'; skip.append(i); continue
        if l.startswith('Terminals'):
            sec = 't'; skip.append(i); continue
        if l.startswith('Nonterminals'):
            sec = 'n'; skip.append(i); continue
        m = re.match(r'^State (\d+)$', l)
        if m:
            sec = 's'; state = m.group(1); lhs = None; skip.append(i); continue
        if sec == 'g':
            m = re.match(r'^\s*(\d+)\s+(?:(\S+):|\|)\s*(.*)$', l)
            if m:
                if m.group(2):
                    lhs = m.group(2)
                gram.append({'rule': m.group(1), 'lhs': lhs, 'rhs': m.group(3).strip()})
                gi.append(i)
        elif sec == 't':
            m = re.match(r'^\s+(\S+)\s+\((\d+)\)\s*(.*)$', l)
            if m:
                term.append({'symbol': m.group(1), 'number': m.group(2), 'rules': m.group(3).strip()})
                ti.append(i)
        elif sec == 'n':
            m = re.match(r'^\s+on (left|right):\s*(.*)$', l)
            if m and cur is not None:
                cur['on ' + m.group(1)] = m.group(2).strip()
                ni.append(i)
                continue
            m = re.match(r'^\s+(\S+)\s+\((\d+)\)\s*$', l)
            if m:
                cur = {'symbol': m.group(1), 'number': m.group(2), 'on left': '', 'on right': ''}
                nont.append(cur)
                ni.append(i)
        elif sec == 's':
            m = re.match(r'^\s*(\d+)\s+(?:(\S+):|\|)\s*(.*?)(?:\s+\[(.*)\])?\s*$', l)
            if m:
                if m.group(2):
                    lhs = m.group(2)
                items.append({'state': state, 'rule': m.group(1), 'lhs': lhs, 'item': m.group(3).strip(), 'lookahead': m.group(4) or ''})
                ii.append(i)
                continue
            m = re.match(r'^\s+(\S+)\s{2,}(.+?)\s*$', l)
            if m:
                act = m.group(2)
                kind, target = act, ''
                a = re.match(r'^(\[)?(shift, and go to state|go to state|reduce using rule)\s+(\d+)(?:\s+\((\S+)\))?\]?$', act)
                if a:
                    kind = a.group(2)
                    if kind.startswith('shift'):
                        kind = 'shift'
                    elif kind.startswith('go'):
                        kind = 'goto'
                    else:
                        kind = 'reduce'
                    if a.group(1):
                        kind = kind + ' (disabled)'
                    target = a.group(3)
                acts.append({'state': state, 'symbol': m.group(1), 'action': kind, 'target': target})
                ai.append(i)
    blocks = []
    for name, recs, idx in (('conflicts', conf, ci), ('grammar', gram, gi), ('terminals', term, ti), ('nonterminals', nont, ni), ('state_items', items, ii), ('state_actions', acts, ai)):
        if recs:
            blocks.append({'name': name, 'kind': 'table', 'lines': idx, 'records': recs})
    return {'blocks': blocks, 'skip': skip}
